protected override void OnModelCreating(ModelBuilder modelBuilder)
{
    // HasIndex throws in EF Core 9 Cosmos — manage indexing via Azure Portal/Bicep.
    modelBuilder.Entity<Product>().ToContainer("Products");

    // EF Core 9 changed the default discriminator property from "Discriminator" to "$type".
    // Preserve the old name so existing 500K documents remain queryable and
    // direct SQL queries referencing c.Discriminator continue to work.
    modelBuilder.Entity<Product>().HasDiscriminator<string>("Discriminator");

    // EF Core 9 changed id format from "Product|123" to "123".
    // Preserve the old compound format so existing documents are still found by FindAsync/point-reads.
    modelBuilder.Entity<Product>().HasRootDiscriminatorInJsonId(true);
}

